input.command:
clickhouse-client --multiquery "
-- Insert a test event
INSERT INTO analytics.raw_events VALUES ('e7', '2026-02-01 08:30:00', 'pv');

-- Verify it flows through to all rollups
SELECT 'hourly', hour, sum(event_count) FROM analytics.rollup_hourly WHERE hour = '2026-02-01 08:00:00' GROUP BY hour;
SELECT 'daily', day, sum(event_count) FROM analytics.rollup_daily WHERE day = '2026-02-01' GROUP BY day;
SELECT 'monthly', month, sum(event_count) FROM analytics.rollup_monthly WHERE month = '2026-02-01' GROUP BY month;
"

clickhouse-client --multiquery "
ALTER TABLE analytics.raw_events DELETE WHERE event_id = 'e7';
ALTER TABLE analytics.rollup_hourly DELETE WHERE hour = '2026-02-01 08:00:00' AND event_count = 1;
" 2>&1 || true

clickhouse-client --multiquery "
OPTIMIZE TABLE analytics.rollup_hourly FINAL;
OPTIMIZE TABLE analytics.rollup_daily FINAL;
OPTIMIZE TABLE analytics.rollup_monthly FINAL;
" && echo "=== HOURLY ===" && clickhouse-client --query "SELECT * FROM analytics.rollup_hourly ORDER BY hour" && echo "=== DAILY ===" && clickhouse-client --query "SELECT * FROM analytics.rollup_daily ORDER BY day" && echo "=== MONTHLY ===" && clickhouse-client --query "SELECT * FROM analytics.rollup_monthly ORDER BY month"

clickhouse-client --multiquery "
TRUNCATE TABLE analytics.rollup_hourly;
TRUNCATE TABLE analytics.rollup_daily;
TRUNCATE TABLE analytics.rollup_monthly;

INSERT INTO analytics.rollup_hourly
SELECT toStartOfHour(event_ts) AS hour, count() AS event_count
FROM analytics.raw_events GROUP BY hour;

INSERT INTO analytics.rollup_daily
SELECT toDate(event_ts) AS day, count() AS event_count
FROM analytics.raw_events GROUP BY day;

INSERT INTO analytics.rollup_monthly
SELECT toStartOfMonth(event_ts) AS month, count() AS event_count
FROM analytics.raw_events GROUP BY month;
"
